package com.mediconnect.repository;
import com.mediconnect.entity.User;import com.mediconnect.enums.UserRole;import com.mediconnect.enums.VerificationStatus;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import java.util.List;import java.util.Optional;import java.util.UUID;
public interface UserRepository extends JpaRepository<User,UUID>{Optional<User> findByEmailIgnoreCase(String email);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select u from User u where lower(u.email)=lower(:email)") Optional<User> findLockedByEmail(@Param("email")String email);long countByRole(UserRole role);List<User> findByRoleAndVerificationStatus(UserRole role,VerificationStatus status);@Query("select u from User u where u.role in :roles and u.verificationStatus='PENDING'")List<User> findPendingProviders(@Param("roles") List<UserRole> roles);@Query("select count(u) from User u where u.role=:role and u.verificationStatus='PENDING'")long countPending(@Param("role")UserRole role);@Query("select count(u) from User u where u.role=:role and u.active=true")long countActiveByRole(@Param("role")UserRole role);}
